{
  "API_calls": [],
  "collected_information": {
    "pytest_configuration": {
      "markers": [
        "telemetry: mark test as a telemetry test (don't mock telemetry)"
      ],
      "testpaths": [
        "lib/crewai/tests",
        "lib/crewai-tools/tests",
        "lib/crewai-files/tests"
      ],
      "asyncio_mode": "strict",
      "asyncio_default_fixture_loop_scope": "function",
      "addopts": "--tb=short -n auto --timeout=60 --dist=loadfile --max-worker-restart=2 --block-network --import-mode=importlib",
      "python_files": "test_*.py",
      "python_classes": "Test*",
      "python_functions": "test_*"
    },
    "ci_workflows": {
      "directory": ".github/workflows/",
      "files": [
        "tests.yml"
      ],
      "note": "Workflows directory contains test-related files but no extracted explicit pytest commands yet."
    },
    "environment_and_test_execution_from_readme": {
      "dependency_management_tool": "uv",
      "commands": [
        "uv lock",
        "uv sync",
        "uv venv",
        "pre-commit install"
      ],
      "test_command": "uv run pytest .",
      "python_version_constraints": ">=3.10, <3.14",
      "notes": "'uv' CLI tool used extensively for environment setup and test execution."
    }
  },
  "terminate": true
}
